"""The artifacts of the test packs, generated by this SDK, are the ones the Go sdk generates
(sdk/internal/testdata/golden, written by `go test ./sdk -run Golden`)."""

import json
import sys
import tempfile
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))  # packsdk
sys.path.insert(0, str(HERE))         # packs

import packsdk
from packs.openbao.pack import OpenBao
from packs.tembo.pack import Tembo

GOLDEN = HERE.parent.parent / "internal" / "testdata" / "golden"


def tree(d: Path) -> list[str]:
    return sorted(p.relative_to(d).as_posix() for p in d.rglob("*") if p.is_file())


class Golden(unittest.TestCase):
    def test_artifacts_equal_gos(self):
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp)
            packsdk.generate(out, OpenBao())
            self.assertEqual(tree(GOLDEN), tree(out))
            for rel in tree(GOLDEN):
                want, got = (GOLDEN / rel).read_bytes(), (out / rel).read_bytes()
                if rel.endswith(".json"):  # the same document; the order of keys is each SDK's
                    self.assertEqual(json.loads(want), json.loads(got), rel)
                else:
                    self.assertEqual(want.decode(), got.decode(), rel)

    def test_a_held_pack_is_generated_alone_too(self):
        with tempfile.TemporaryDirectory() as tmp:
            packsdk.generate(tmp, Tembo())
            self.assertEqual(["tembo/pack.yaml", "tembo/schema.json", "tembo/templates/tembo.env.ptmpl"], tree(Path(tmp)))

    def test_generation_is_stable(self):
        with tempfile.TemporaryDirectory() as a, tempfile.TemporaryDirectory() as b:
            packsdk.generate(a, OpenBao())
            packsdk.generate(b, OpenBao())
            for rel in tree(Path(a)):
                self.assertEqual((Path(a) / rel).read_bytes(), (Path(b) / rel).read_bytes())


class Paths(unittest.TestCase):
    def test_pointer_and_dotted_come_from_the_fields(self):
        o = OpenBao()
        self.assertEqual("/openbao/storage", packsdk.pointer(o, lambda p: p.bao.storage))
        self.assertEqual("openbao.api_addr", packsdk.dotted(o, lambda p: p.bao.api_addr))
        self.assertEqual("postgres", packsdk.dotted(o, lambda p: p.postgres))
        self.assertEqual("/postgres/node/nofailover", packsdk.pointer(o, lambda p: p.postgres.node.nofailover))

    def test_a_field_that_is_not_there_is_refused(self):
        with self.assertRaises(packsdk.SchemaError):
            packsdk.pointer(OpenBao(), lambda p: p.bao.nope)
        with self.assertRaises(packsdk.SchemaError):
            packsdk.pointer(OpenBao(), lambda p: p)


class Escapes(unittest.TestCase):
    def test_html_is_escaped_the_way_encoding_json_does(self):
        from dataclasses import dataclass
        from packsdk import Meta, Pack, Root, field

        @dataclass
        class Lt(Pack):
            f: str = field("a<b&c>d", omitempty=True)
            def meta(self): return Meta(name="lt", version="1")
            def pack_root(self): return Root()

        raw = packsdk.schema(Lt()).decode()
        self.assertIn("a\\u003cb\\u0026c\\u003ed", raw)
        self.assertEqual("a<b&c>d", json.loads(raw)["properties"]["f"]["default"])

    def test_a_constraint_of_another_type_is_refused(self):
        # a schema no value passes is not written: an enum of another type, a bound of a string, a length of a number
        from dataclasses import dataclass
        from packsdk import Meta, Pack, Root, field

        for name, (tp, f) in {"an enum of another type": (int, lambda: field(0, enum=["a"])),
                              "a bound of a string": (str, lambda: field("", minimum=1)),
                              "a length of a number": (int, lambda: field(0, max_length=3)),
                              "a fractional length": (str, lambda: field("", max_length=1.5))}.items():
            @dataclass
            class Bad(Pack):
                v: tp = f()
                def meta(self): return Meta(name="bad", version="1")
                def pack_root(self): return Root()
            with self.subTest(name), self.assertRaises(packsdk.SchemaError):
                packsdk.schema(Bad())


class Refusals(unittest.TestCase):
    def test_a_template_that_is_not_in_content(self):
        from dataclasses import dataclass
        from packsdk import Meta, Pack, Root, field

        @dataclass
        class Lost(Pack):
            f: str = field("", omitempty=True)
            def meta(self): return Meta(name="lost", version="1", dir=str(HERE))
            def pack_root(self): return Root(content=[packsdk.File(path="/etc/x.conf", template="lost.ptmpl")])

        with self.assertRaisesRegex(packsdk.SchemaError, "lost.ptmpl"):
            packsdk.pack_file(Lost())

    def test_packs_lists_what_is_held_once(self):
        # Tembo does not hold itself; a loop is made by two packs naming each other and is refused by name
        self.assertEqual(["openbao", "tembo"], [p.meta().name for p in packsdk.packs(OpenBao())])


if __name__ == "__main__":
    unittest.main()
